/**
 * @file focus-manager.ts
 * @copyright 2021-2026, Firaxis Games
 * @description Handles focus management of UI elements and navigation between UI elements
 */
import { createEffect, createMemo, createSignal, on, onCleanup, onMount, useContext } from "solid-js";

import { Audio } from "#core/ui/audio-base/audio-support.js";
import { buildFocusChain, currentSolidFocus, FocusContext, rootFocus } from "#core/ui-next/services/focus.js";
import { ModelLifecycle, ModelRegistry } from "#core/ui-next/services/model-registry.js";

declare global {
	var debugCurrentFocus: WeakRef<HTMLElement>; // eslint-disable-line no-var
}

function createFocusManager() {
	const [enabledDebugFocus, setEnableDebugFocus] = createSignal<boolean>(false);
	const [activeElement, setActiveElement] = createSignal(document.activeElement);
	const [currentFocus, setCurrentFocus] = createSignal<HTMLElement>(document.body);
	const [pendingFocus, setPendingFocus] = createSignal<HTMLElement | null>(null);
	const [isPendingFocusSolid, setIsPendingFocusSolid] = createSignal<boolean>(false);
	const [pendingFocusFrameCount, setPendingFocusFrameCount] = createSignal(0);
	const [lockedFocusTarget, setLockedFocusTarget] = createSignal<{
		previous: HTMLElement | null;
		who: string;
	} | null>();
	const [isGamepadActive, setIsGamePadActive] = createSignal(
		Input.getActiveDeviceType() == InputDeviceType.Controller,
	);

	const isFocusActive = createMemo(() => activeElement() == currentFocus() && currentFocus() != document.body);
	const isWorldFocused = createMemo(() => currentFocus() == document.body);
	const isFocusLocked = createMemo(() => lockedFocusTarget() != null);
	const focusChain = createMemo(() => buildFocusChain(currentFocus()));
	let focusAudioDebounce = false;

	function handleDeviceChanged(deviceType: InputDeviceType) {
		setIsGamePadActive(deviceType == InputDeviceType.Controller);

		if (isGamepadActive()) {
			realizeFocus(false);
		}
	}

	const solidRootFocus = useContext(FocusContext);

	// Set the current focus in a 'global' variable which is useful for debugging in Chrome/VS Code.
	createEffect(() => {
		globalThis.debugCurrentFocus = new WeakRef(currentFocus());
	});

	createEffect(
		on(
			() => currentSolidFocus(),
			(element) => {
				if (element) {
					setFocusInternal(element, false);
				}
			},
		),
	);

	onMount(() => {
		window.addEventListener("blur", handleFocusChange, true);
		window.addEventListener("focus", handleFocusChange, true);

		engine.on("input-source-changed", handleDeviceChanged);
	});

	onCleanup(() => {
		window.removeEventListener("blur", handleFocusChange, true);
		window.addEventListener("focus", handleFocusChange, true);

		engine.off("input-source-changed", handleDeviceChanged);
	});

	function handleFocusChange() {
		setActiveElement(document.activeElement);
	}

	/**
	 * Obtain the first focusable descendant of a parent which is in the focus chain.
	 * @param {Elment} parent The parent in the focus chain,
	 * @returns {Element|null} null if parent isn't in focus chain or if this is the current focused element, otherwise the first focusable item that is the decendant of the parent
	 */
	function getFocusChildOf(parent: Element): Element | null {
		let index = -1;

		// Equivilent of FindIndex();
		const focusChainLength = focusChain().length;
		for (let i = 0; i < focusChainLength; ++i) {
			if (focusChain()[i].deref() == parent) {
				index = i;
				break;
			}
		}

		// FindIndex() - 1.
		index = index - 1;

		if (index < 0) {
			// The parent is not in the focus chain or it is the current focused element
			return null;
		}

		while (index > 0) {
			const el = focusChain()[index].deref();
			if (el && el.hasAttribute("tabindex")) {
				return el;
			}
			index--;
		}

		// Return null or the derefed first item in the chain.
		return focusChain().length > 0 ? (focusChain()[0].deref() ?? null) : null;
	}

	/**
	 * Helper for writing out information about a target Element to a log string.
	 * @param {Element} target (optional) The target in question, or the current focus if not specified.
	 * @returns string representation some unique identifiers of the target
	 */
	function toLogString(target: Element | null): string {
		const element = target ?? currentFocus();
		return `name=${element?.nodeName ?? ""}, tagName=${element?.tagName ?? ""}, className=${element?.className ?? ""}`;
	}

	/**
	 * Set the focus an prevent anyone else from setting it until it's unlocked.
	 **/
	function lockFocus(target: Element, who: string, why: string): boolean {
		console.log(`FM: Focus lock requested by '${who}' on ${toLogString(target)}, because '${why}'.`);
		if (isFocusLocked()) {
			console.error(`FM: Denying focus lock because already locked by ${lockedFocusTarget()?.who}.`);
			return false;
		}

		if (target instanceof HTMLElement) {
			setLockedFocusTarget({ previous: currentFocus(), who });
		} else {
			console.error(`FM: Denying focus lock because target ${target} is not an HTMLElement.`);
			return false;
		}

		setPendingFocus(target);
		window.requestAnimationFrame(checkPendingFocus);
		return true;
	}

	function unlockFocus(target: Element, who: string): boolean {
		console.log(`FM: Focus unlock by '${who}' on ${toLogString(target)}.`);
		if (!isFocusLocked()) {
			console.error(`FM: Attempting to unlock focus by ${who} but it's already unlocked.`);
			return false;
		}

		const oldWho = lockedFocusTarget()?.who;
		if (oldWho != who) {
			console.error(`FM: Fail to unlock focus by ${who} as it was locked by ${oldWho}`);
			return false;
		}

		if (target != currentFocus()) {
			console.error(
				`FM: Fail to unlock focus by ${who} because the target '${toLogString(target)}' mismatches the currentFocus '${toLogString(currentFocus())}'.`,
			);
			return false;
		}

		setPendingFocus(lockedFocusTarget()?.previous ?? null);
		setLockedFocusTarget(undefined);

		window.requestAnimationFrame(checkPendingFocus);
		return true;
	}

	function setFocus(target: Element) {
		// Solid sets a focus context name on all focusables - we can use that to detect if we are focusing a solid element
		setFocusInternal(target, target.hasAttribute("data-focus-context-name"));
	}

	/**
	 * Set the focus to a particular element.
	 * @param {Element} target element to focus, needs to have a "tabindex" attribute
	 */
	function setFocusInternal(target: Element, applySolidFocus: boolean) {
		if (target == null || target == undefined) {
			console.error("FM: Attempt to set focus to a null/undefined type.");
			return;
		}

		if (target == document.body) {
			// Allowed but not great.
			console.warn(
				"FM: Explicitly setting focus to the document.body (aka: 'the world').  Use worldFocused() instead!",
			);
		} else if (target.hasAttribute("tabindex") == false) {
			// Everything needs a tabindex, Components don't have to have the tabindex on it as long as it's not yet initialized.
			if (target instanceof ComponentRoot == false || (target as ComponentRoot).isInitialized) {
				console.error("FM: Attempt to set focus on element without tabindex. element: ", toLogString(target));
			}
		}

		if (isFocusLocked()) {
			if (target instanceof HTMLElement) {
				if (target != currentFocus()) {
					console.warn(
						`FM: Focus is locked. Previous focus '${toLogString(lockedFocusTarget()!.previous)}' overriden by set focus call for '${toLogString(target)}'.`,
					);

					setLockedFocusTarget((l) => ({ previous: target, who: l?.who ?? "" }));
				}
			} else {
				console.error(
					`FM: Focus is locked and attempt to overwrite with non HTML element: '${toLogString(target)}'.`,
				);
			}

			return;
		}

		// Provide warnings if something else was waiting to focus and it's now changed.
		if (target.isSameNode(pendingFocus())) {
			console.warn("FM: Multiple attempts to set focus, currently pending. target: ", toLogString(target));
		} else if (pendingFocus()) {
			if (!pendingFocus()!.contains(target)) {
				// Only ignore new focus if it is deeper down the tree from the current pending focus.
				console.warn(
					`FM: Setting focus to '${toLogString(target)}' and a pending focus '${toLogString(pendingFocus())}' will never be realized.`,
				);
			}
		}

		setPendingFocus(null); // Clear, about to attempt setting it now.
		setIsPendingFocusSolid(false);

		if (!target.isSameNode(currentFocus())) {
			// Only set focus if it's different from current one.
			if (target instanceof HTMLHtmlElement) {
				// Document assignment
				setCurrentFocus(document.body);
			} else if (target instanceof HTMLElement) {
				if (readyForFocus(target)) {
					// Normal assignment
					setCurrentFocus(target);
				} else {
					if (pendingFocus()) {
						// should be impossible
						console.error(
							"FM: Overriding a pending focus target with a new one. old: ",
							toLogString(pendingFocus()),
							",  new: ",
							toLogString(target),
						);
					}
					clearFocus();
					setIsPendingFocusSolid(target.hasAttribute("data-focus-context-name"));
					setPendingFocus(target);
					window.requestAnimationFrame(checkPendingFocus);
					return; // Not ready to build a new focus chain or realize focus.
				}
			} else {
				// TODO: Any non-HTML element based targets?
				console.warn(
					"FM: Attempt to setFocus on non-HTML element; wasn't expecting that: " + toLogString(target),
				);
				return;
			}
			realizeFocus(applySolidFocus);
		}
	}

	/**
	 * Is an element ready to receive focus from the focus manager.
	 * @param element An HTMLElement
	 * @returns true if it can be set focus.
	 */
	function readyForFocus(element: Element): boolean {
		return element.isConnected && element.hasAttribute("tabindex");
	}

	function handleFocusLost() {
		console.warn("FM: Needing to walk up focus chain to to disconnect currentFocus: ", toLogString(currentFocus())); // Remove warning if there are acceptable cases of this occuring

		// Walk up the focus chain
		for (let i = focusChain.length - 2; i >= 0; --i) {
			const el = focusChain()[i].deref();
			if (el && readyForFocus(el)) {
				setCurrentFocus(el);
				break;
			}
		}

		// If here due to empty focus chain, the last item should be the document.
		setCurrentFocus(document.body);
	}

	/**
	 * Show or hide focus based on the environment.
	 */
	function realizeFocus(applySolidFocus: boolean) {
		let curFocus = currentFocus();

		// If focus is no longer connected, walk up the chain.
		if (!curFocus || !curFocus.isConnected) {
			handleFocusLost();
			curFocus = currentFocus();
		}

		if (!curFocus) {
			return;
		}

		if (isGamepadActive()) {
			// Because recursion can occur here, let's take note of what the current focus was before we trigger the possible recursion.
			const prevFocus = curFocus;

			// Visually set the focus; if a slot or panel may respond by setting focus on (default) child... may cascade towards a leaf child that wants focus.
			curFocus.focus();

			// If the element was recently made visible, we must 2 frames in order to properly set the focus state.
			// This is because focus() depends on the node's layout tree from the main thread.
			const handleSetFocus = () => {
				if (applySolidFocus) {
					solidRootFocus.focusDescendant(currentFocus(), false);
				}

				// If we're still setting the focus to what we were originally called for, go ahead and play that element's focus sound if it has one.
				// Only on the last recursive call will we be setting the focus to the actual final target.
				// This is debounced so only 1 of thse will ever play in a frame
				if (prevFocus == curFocus && !focusAudioDebounce) {
					const audioId = curFocus.getAttribute("data-audio-focus-ref") || "data-audio-focus";
					const audioGroup = curFocus.getAttribute("data-audio-group-ref") || "audio-base";

					Audio.playSound(audioId, audioGroup);
					focusAudioDebounce = true;

					requestAnimationFrame(() => {
						focusAudioDebounce = false;
					});
				}
			};

			if (document.activeElement != curFocus) {
				//eslint-disable-next-line solid/reactivity
				waitForLayout(() => {
					if (!curFocus.isConnected || curFocus != currentFocus()) {
						return;
					}

					curFocus.focus();

					if (document.activeElement == curFocus) {
						handleSetFocus();
					} else {
						// Account for the situation where focus was changed within an onFocus event.
						if (currentFocus() == curFocus) {
							console.log(
								`Despite waiting 2 frames, could not set focus on <${curFocus.tagName} #${curFocus.id} - ${curFocus.className}>.`,
							);
						}
					}
				});
			} else {
				handleSetFocus();
			}

			if (enabledDebugFocus()) {
				curFocus.classList.add("debug-visualize-focus");
			}
		} else {
			curFocus.blur(); // No gamepad, turn off visually focused

			if (enabledDebugFocus()) {
				curFocus.classList.remove("debug-visualize-focus");
			}
		}
	}

	/**
	 * Check if a pending focus is ready to gain focus.
	 */
	function checkPendingFocus() {
		if (!pendingFocus()) {
			// Nothing pending, bail. (An old pending focus may have been never realized because of a new  set focus call.)
			return;
		}

		if (readyForFocus(pendingFocus()!)) {
			setCurrentFocus(pendingFocus()!);
			realizeFocus(isPendingFocusSolid());
			setPendingFocus(null);
			setIsPendingFocusSolid(false);
			setPendingFocusFrameCount(0);
		} else {
			// Safety checks to mitigate hangs:
			setPendingFocusFrameCount((count) => count + 1);

			if (pendingFocusFrameCount() == 10) {
				console.warn(
					"FM: Over 10 frames have been requested for element to receive focus: ",
					toLogString(pendingFocus()),
				);
			}

			if (pendingFocusFrameCount() == 30) {
				console.error(
					`FM: Forcing focus re-evaluation as a pending focus element has been waiting over ${pendingFocusFrameCount()} frames for focus: ${toLogString(pendingFocus())}`,
				);

				setPendingFocus(null);
				setPendingFocusFrameCount(0);

				// Focus the body if we lose context completely
				// If solid focus is pending, use the solid focus chain from body instead
				if (isPendingFocusSolid()) {
					setIsPendingFocusSolid(false);
					rootFocus.focusCurrent();
				} else {
					setFocus(document.body);
				}
			}

			window.requestAnimationFrame(checkPendingFocus); // Pending not connected, check next frame.
		}
	}

	/**
	 * Clears the current focused element and sets focus to the world (document.body)
	 * @param {HTMLElement|null} targetElement - When set, only clear if its the current focus or the current focus is desecendent of it.
	 */
	function clearFocus(targetElement: HTMLElement | null = null) {
		if (currentFocus() == null) {
			// Should be impossible
			console.error("FM: Clear focus but focus is null!");
			return;
		}

		if (currentFocus() == document.body && activeElement() == document.body) {
			// Already cleared
			return;
		}

		if (isFocusLocked()) {
			console.warn(
				`FM: Denying clearFocus('${targetElement ? toLogString(targetElement) : ""}') because focus is locked by ${lockedFocusTarget()?.who}.`,
			);
			return;
		}

		if (targetElement != null) {
			if (!currentFocus().isConnected) {
				console.error(
					"FM: Attempt to clear focus with an element and current focus is set to a disconnected DOM node. current: ",
					toLogString(currentFocus()),
					", target: ",
					toLogString(targetElement),
				);
				console.warn("FM: Will be clearing focus regardless of targetElement to prevent lock up.");
				return; // leave, focus isn't connected
			} else {
				if (currentFocus() != targetElement && !targetElement.contains(currentFocus())) {
					// current isn't the target, nor does the target specify somehow contain the current
					if (targetElement.querySelector(":focus") == null) {
						// sanity check (needed?) target itself isn't focused
						return; // leave since focus cannot be cleared due to failing target filter
					}
				}
			}
		}

		currentFocus()?.blur();

		if (enabledDebugFocus()) {
			currentFocus().classList.remove("debug-visualize-focus");
		}

		setCurrentFocus(document.body);
	}

	return {
		activeElement,
		currentFocus,
		setFocus,
		clearFocus,
		isFocusActive,
		isWorldFocused,
		lockFocus,
		unlockFocus,
		isFocusLocked,
		getFocusChildOf,
		setEnableDebugFocus,
		realizeFocus,
		toLogString,
	};
}

export const FocusManager = ModelRegistry.register("FocusManager", ModelLifecycle.Singleton, createFocusManager);
